-- 11 workshop EIU FabLab 2026 thay khối "Sự kiện & hội thảo" cũ (2019–2022), API 24.
-- SINH BẰNG MÁY từ src/i18n (vi.js / en.js). Nguồn: tài liệu "Workshop EIU FabLab 2026" người
-- dùng soạn từ fanpage FabLab – EIU.
--
-- Section `activities`, mỗi ngôn ngữ MỘT câu UPDATE (`rev` +1 mỗi câu → +2), chốt theo TỪNG
-- ngôn ngữ bằng id 'ws26-clay' (chạy lại không đổi gì):
-- - `items`: giữ nguyên, theo thứ tự cũ, mọi mục có `kind` KHÔNG thuộc khối 'events' (Cuộc thi,
--   kể cả mục admin tự thêm); bỏ mọi mục của khối events; nối 11 workshop mới (mới nhất trước,
--   đều `registerClosed`). `uav-f1tenth` (admin tạo) được thay bằng bản theo tài liệu — ảnh và
--   video nằm ở `binding` theo id nên giữ nguyên;
-- - nhãn `timeLabel` / `venueLabel` / `feeLabel` cho dòng giờ · địa điểm · chi phí;
-- - mô tả khối events chỉ đổi khi còn NGUYÊN VĂN cũ (admin đã sửa thì giữ).
-- Binding ảnh của các mục cũ để lại (mồ côi có chủ đích). Ảnh 10 workshop mới KHÔNG gắn ở đây
-- (SQL không xử lý file): `npm run images:replace -- activity --missing`.

-- vi
UPDATE section
   SET json = CASE WHEN (SELECT '$.groups[' || key || '].description' FROM json_each(section.json, '$.groups') WHERE json_extract(value, '$.id') = 'events' AND json_extract(value, '$.description') = 'Hội thảo chuyên đề, workshop thực hành và lễ hợp tác diễn ra tại FabLab trong khoảng 2019–2023.') IS NOT NULL THEN json_set(json_set(json, '$.items', (SELECT json_group_array(json(v) ORDER BY part, o) FROM (SELECT value AS v, 0 AS part, CAST(key AS INTEGER) AS o FROM json_each(section.json, '$.items') WHERE json_extract(value, '$.kind') NOT IN (SELECT k.value FROM json_each(section.json, '$.groups') g, json_each(g.value, '$.kinds') k WHERE json_extract(g.value, '$.id') = 'events') AND json_extract(value, '$.id') NOT IN ('ws26-fablab-intro', 'ws26-lantern', 'ws26-bouquet', 'ws26-decoden', 'ws26-beads', 'ws26-glass', 'ws26-clay', 'ws26-git', 'ws26-mech-design', 'uav-f1tenth', 'ws26-machines') UNION ALL SELECT value, 1, CAST(key AS INTEGER) FROM json_each('[{"id":"ws26-fablab-intro","kind":"workshop","date":"21/10/2026","title":"Hướng dẫn sử dụng FabLab","description":"Buổi giới thiệu không gian sáng tạo FabLab cho sinh viên. Người tham gia làm quen với các thiết bị công nghệ, tìm hiểu quy trình sử dụng và cách ứng dụng chúng trong học tập, nghiên cứu, thực hành, để biến ý tưởng thành sản phẩm thực tế.","venue":"EIU FabLab, Block B11","registerClosed":true},{"id":"ws26-lantern","kind":"workshop","date":"23/9/2026","title":"Làm lồng đèn Trung thu","description":"Workshop tự làm đèn lồng Trung thu bằng gỗ và mica, có dùng máy cắt/khắc laser. Người tham gia được hướng dẫn lên ý tưởng và chọn mẫu, lắp ráp theo mẫu, rồi trang trí và hoàn thiện sản phẩm.","time":"Thứ Tư, 14:00–16:00","venue":"Phòng 204.B11, FabLab EIU","fee":"60.000 đ","registerClosed":true},{"id":"ws26-bouquet","kind":"workshop","date":"12/8/2026","title":"Bó hoa thanh xuân","description":"Workshop DIY làm bó hoa handmade tặng người thân hoặc tặng chính mình. Người tham gia kết hợp những cành hoa nhỏ và các nhân vật tự nặn bằng tay thành một bó hoa mang dấu ấn riêng, kèm lời chúc gửi gắm qua từng chi tiết.","time":"Thứ Tư, 14:00–16:00","venue":"Phòng 202.B11, FabLab EIU","registerClosed":true},{"id":"ws26-decoden","kind":"workshop","date":"22/7/2026","title":"Trang trí kem keo","description":"Workshop DIY trang trí đồ dùng bằng kem keo và charm. Người tham gia tự trang trí lược chải tóc, ốp lưng điện thoại, gương và các phụ kiện khác, mỗi món mang cá tính riêng.","time":"Thứ Tư, ca sáng 9:00–11:00, ca chiều 14:00–16:00","venue":"Phòng 202.B11, FabLab EIU","fee":"35.000 đ/người","registerClosed":true},{"id":"ws26-beads","kind":"workshop","date":"1/7/2026","title":"Xỏ hạt đan vòng","description":"Workshop DIY trong chuỗi workshop thủ công. Người tham gia tự thiết kế và xỏ các hạt cườm thành chiếc vòng của riêng mình, tự do chọn màu sắc và chi tiết, làm xong được mang về. Mỗi sản phẩm là một món quà nhỏ thể hiện sự tỉ mỉ và cá tính của người làm.","time":"Thứ Tư, chia ca sáng và ca chiều","venue":"Phòng 305.B11, FabLab EIU","registerClosed":true},{"id":"ws26-glass","kind":"workshop","date":"10/6/2026","title":"Trang trí ly thủy tinh","description":"Workshop DIY tạo không khí vui vẻ, thư giãn cho sinh viên sau giờ học. Mỗi người tự thiết kế và trang trí một chiếc ly thủy tinh theo phong cách riêng. Buổi học diễn ra sôi nổi, mỗi chiếc ly là một tác phẩm mang dấu ấn của người làm.","time":"Thứ Tư, ca sáng 9:00–11:00, ca chiều 14:00–16:00","venue":"Phòng 305.B11, FabLab EIU","fee":"35.000 đ/người (đã gồm vật tư)","registerClosed":true},{"id":"ws26-clay","kind":"workshop","date":"27/5/2026","title":"Creating with Clay – tạo hình đất sét","description":"Workshop DIY giúp sinh viên thư giãn và kết nối sau giờ học. Người tham gia dùng đất sét tự khô Mont Marte và màu acrylic để nặn các sản phẩm nhỏ xinh, làm xong được mang về. Sinh viên và cả chuyên viên của trường cùng tham gia.","time":"Thứ Tư, ca 1 9:00–11:00, ca 2 14:00–16:00","venue":"Phòng 209.B11, FabLab EIU","fee":"35.000 đ/người (đã gồm vật tư)","registerClosed":true},{"id":"ws26-git","kind":"workshop","date":"20/5/2026","title":"Hướng dẫn sử dụng Git, GitHub","description":"Workshop giúp sinh viên quản lý mã nguồn, làm việc nhóm và “cứu hộ code” cho đồ án. Người tham gia học Git và GitHub từ con số 0, quy trình pull → add → commit → push, làm việc với nhánh (branch, merge) và thực hành làm việc nhóm trực tiếp. Buổi học thu hút đông đảo sinh viên yêu thích lập trình.","time":"Thứ Tư, 14:00–16:00","venue":"Phòng 305.B11, FabLab EIU","registerClosed":true},{"id":"ws26-mech-design","kind":"workshop","date":"15/4/2026","title":"Thiết kế cơ khí cơ bản","description":"Workshop cho sinh viên đam mê kỹ thuật, cần tìm hiểu thiết kế cơ khí cho đồ án hoặc dự án cá nhân. Nội dung gồm tư duy thiết kế cơ khí, các tiêu chuẩn kỹ thuật và thực hành thiết kế trên phần mềm, với phần chia sẻ và nhiều giờ thực hành tập trung.","time":"Thứ Tư, 14:00–16:00","venue":"Phòng 305.B11, FabLab EIU","registerClosed":true},{"id":"uav-f1tenth","kind":"workshop","date":"27/1/2026","title":"Chuỗi workshop UAV & F1TENTH","description":"Chuỗi workshop dài hạn cho sinh viên quan tâm đến robot tự hành, bắt đầu từ 27/01/2026. Giai đoạn 1 trang bị kiến thức nền tảng: Ubuntu và Linux, toán nền tảng, ROS 2 và các khái niệm cốt lõi, lập trình ROS 2 trên mô phỏng rồi kết nối với drone và xe F1TENTH thật — chuẩn bị cho phần chuyên sâu ở giai đoạn 2.","details":"Làm quen Ubuntu và môi trường Linux.\n\nÔn toán nền tảng: giải tích, đại số tuyến tính, xác suất – thống kê.\n\nROS 2 và các khái niệm cốt lõi: Workspace, Package, Node, Topic, Service, Action.\n\nLập trình ROS 2 trên môi trường mô phỏng, rồi kết nối với mô hình thực tế như drone và xe F1TENTH.","registerClosed":true},{"id":"ws26-machines","kind":"workshop","date":"14/1/2026","title":"Hướng dẫn sử dụng máy móc tại xưởng FabLab","description":"Workshop dành cho sinh viên thích chế tạo, kỹ thuật, DIY hoặc cần dùng máy móc cho đồ án và dự án cá nhân. Người tham gia được học quy trình và quy định an toàn khi làm việc tại FabLab, thực hành trực tiếp với các máy cơ khí cơ bản, để tự tin dùng máy cho học tập, nghiên cứu và làm sản phẩm.","time":"Thứ Tư, ca sáng 9:00–11:00, ca chiều 14:00–16:00","venue":"Phòng 204.B11, FabLab EIU","registerClosed":true}]'))), '$.timeLabel', 'Thời gian', '$.venueLabel', 'Địa điểm', '$.feeLabel', 'Chi phí'), (SELECT '$.groups[' || key || '].description' FROM json_each(section.json, '$.groups') WHERE json_extract(value, '$.id') = 'events' AND json_extract(value, '$.description') = 'Hội thảo chuyên đề, workshop thực hành và lễ hợp tác diễn ra tại FabLab trong khoảng 2019–2023.'), 'Workshop kỹ thuật cho sinh viên, workshop thủ công DIY và buổi hướng dẫn sử dụng FabLab trong năm 2026.') ELSE json_set(json, '$.items', (SELECT json_group_array(json(v) ORDER BY part, o) FROM (SELECT value AS v, 0 AS part, CAST(key AS INTEGER) AS o FROM json_each(section.json, '$.items') WHERE json_extract(value, '$.kind') NOT IN (SELECT k.value FROM json_each(section.json, '$.groups') g, json_each(g.value, '$.kinds') k WHERE json_extract(g.value, '$.id') = 'events') AND json_extract(value, '$.id') NOT IN ('ws26-fablab-intro', 'ws26-lantern', 'ws26-bouquet', 'ws26-decoden', 'ws26-beads', 'ws26-glass', 'ws26-clay', 'ws26-git', 'ws26-mech-design', 'uav-f1tenth', 'ws26-machines') UNION ALL SELECT value, 1, CAST(key AS INTEGER) FROM json_each('[{"id":"ws26-fablab-intro","kind":"workshop","date":"21/10/2026","title":"Hướng dẫn sử dụng FabLab","description":"Buổi giới thiệu không gian sáng tạo FabLab cho sinh viên. Người tham gia làm quen với các thiết bị công nghệ, tìm hiểu quy trình sử dụng và cách ứng dụng chúng trong học tập, nghiên cứu, thực hành, để biến ý tưởng thành sản phẩm thực tế.","venue":"EIU FabLab, Block B11","registerClosed":true},{"id":"ws26-lantern","kind":"workshop","date":"23/9/2026","title":"Làm lồng đèn Trung thu","description":"Workshop tự làm đèn lồng Trung thu bằng gỗ và mica, có dùng máy cắt/khắc laser. Người tham gia được hướng dẫn lên ý tưởng và chọn mẫu, lắp ráp theo mẫu, rồi trang trí và hoàn thiện sản phẩm.","time":"Thứ Tư, 14:00–16:00","venue":"Phòng 204.B11, FabLab EIU","fee":"60.000 đ","registerClosed":true},{"id":"ws26-bouquet","kind":"workshop","date":"12/8/2026","title":"Bó hoa thanh xuân","description":"Workshop DIY làm bó hoa handmade tặng người thân hoặc tặng chính mình. Người tham gia kết hợp những cành hoa nhỏ và các nhân vật tự nặn bằng tay thành một bó hoa mang dấu ấn riêng, kèm lời chúc gửi gắm qua từng chi tiết.","time":"Thứ Tư, 14:00–16:00","venue":"Phòng 202.B11, FabLab EIU","registerClosed":true},{"id":"ws26-decoden","kind":"workshop","date":"22/7/2026","title":"Trang trí kem keo","description":"Workshop DIY trang trí đồ dùng bằng kem keo và charm. Người tham gia tự trang trí lược chải tóc, ốp lưng điện thoại, gương và các phụ kiện khác, mỗi món mang cá tính riêng.","time":"Thứ Tư, ca sáng 9:00–11:00, ca chiều 14:00–16:00","venue":"Phòng 202.B11, FabLab EIU","fee":"35.000 đ/người","registerClosed":true},{"id":"ws26-beads","kind":"workshop","date":"1/7/2026","title":"Xỏ hạt đan vòng","description":"Workshop DIY trong chuỗi workshop thủ công. Người tham gia tự thiết kế và xỏ các hạt cườm thành chiếc vòng của riêng mình, tự do chọn màu sắc và chi tiết, làm xong được mang về. Mỗi sản phẩm là một món quà nhỏ thể hiện sự tỉ mỉ và cá tính của người làm.","time":"Thứ Tư, chia ca sáng và ca chiều","venue":"Phòng 305.B11, FabLab EIU","registerClosed":true},{"id":"ws26-glass","kind":"workshop","date":"10/6/2026","title":"Trang trí ly thủy tinh","description":"Workshop DIY tạo không khí vui vẻ, thư giãn cho sinh viên sau giờ học. Mỗi người tự thiết kế và trang trí một chiếc ly thủy tinh theo phong cách riêng. Buổi học diễn ra sôi nổi, mỗi chiếc ly là một tác phẩm mang dấu ấn của người làm.","time":"Thứ Tư, ca sáng 9:00–11:00, ca chiều 14:00–16:00","venue":"Phòng 305.B11, FabLab EIU","fee":"35.000 đ/người (đã gồm vật tư)","registerClosed":true},{"id":"ws26-clay","kind":"workshop","date":"27/5/2026","title":"Creating with Clay – tạo hình đất sét","description":"Workshop DIY giúp sinh viên thư giãn và kết nối sau giờ học. Người tham gia dùng đất sét tự khô Mont Marte và màu acrylic để nặn các sản phẩm nhỏ xinh, làm xong được mang về. Sinh viên và cả chuyên viên của trường cùng tham gia.","time":"Thứ Tư, ca 1 9:00–11:00, ca 2 14:00–16:00","venue":"Phòng 209.B11, FabLab EIU","fee":"35.000 đ/người (đã gồm vật tư)","registerClosed":true},{"id":"ws26-git","kind":"workshop","date":"20/5/2026","title":"Hướng dẫn sử dụng Git, GitHub","description":"Workshop giúp sinh viên quản lý mã nguồn, làm việc nhóm và “cứu hộ code” cho đồ án. Người tham gia học Git và GitHub từ con số 0, quy trình pull → add → commit → push, làm việc với nhánh (branch, merge) và thực hành làm việc nhóm trực tiếp. Buổi học thu hút đông đảo sinh viên yêu thích lập trình.","time":"Thứ Tư, 14:00–16:00","venue":"Phòng 305.B11, FabLab EIU","registerClosed":true},{"id":"ws26-mech-design","kind":"workshop","date":"15/4/2026","title":"Thiết kế cơ khí cơ bản","description":"Workshop cho sinh viên đam mê kỹ thuật, cần tìm hiểu thiết kế cơ khí cho đồ án hoặc dự án cá nhân. Nội dung gồm tư duy thiết kế cơ khí, các tiêu chuẩn kỹ thuật và thực hành thiết kế trên phần mềm, với phần chia sẻ và nhiều giờ thực hành tập trung.","time":"Thứ Tư, 14:00–16:00","venue":"Phòng 305.B11, FabLab EIU","registerClosed":true},{"id":"uav-f1tenth","kind":"workshop","date":"27/1/2026","title":"Chuỗi workshop UAV & F1TENTH","description":"Chuỗi workshop dài hạn cho sinh viên quan tâm đến robot tự hành, bắt đầu từ 27/01/2026. Giai đoạn 1 trang bị kiến thức nền tảng: Ubuntu và Linux, toán nền tảng, ROS 2 và các khái niệm cốt lõi, lập trình ROS 2 trên mô phỏng rồi kết nối với drone và xe F1TENTH thật — chuẩn bị cho phần chuyên sâu ở giai đoạn 2.","details":"Làm quen Ubuntu và môi trường Linux.\n\nÔn toán nền tảng: giải tích, đại số tuyến tính, xác suất – thống kê.\n\nROS 2 và các khái niệm cốt lõi: Workspace, Package, Node, Topic, Service, Action.\n\nLập trình ROS 2 trên môi trường mô phỏng, rồi kết nối với mô hình thực tế như drone và xe F1TENTH.","registerClosed":true},{"id":"ws26-machines","kind":"workshop","date":"14/1/2026","title":"Hướng dẫn sử dụng máy móc tại xưởng FabLab","description":"Workshop dành cho sinh viên thích chế tạo, kỹ thuật, DIY hoặc cần dùng máy móc cho đồ án và dự án cá nhân. Người tham gia được học quy trình và quy định an toàn khi làm việc tại FabLab, thực hành trực tiếp với các máy cơ khí cơ bản, để tự tin dùng máy cho học tập, nghiên cứu và làm sản phẩm.","time":"Thứ Tư, ca sáng 9:00–11:00, ca chiều 14:00–16:00","venue":"Phòng 204.B11, FabLab EIU","registerClosed":true}]'))), '$.timeLabel', 'Thời gian', '$.venueLabel', 'Địa điểm', '$.feeLabel', 'Chi phí') END,
       rev = rev + 1,
       updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
 WHERE key = 'activities' AND locale = 'vi'
   AND NOT EXISTS (SELECT 1 FROM json_each(section.json, '$.items') WHERE json_extract(value, '$.id') = 'ws26-clay');

-- en
UPDATE section
   SET json = CASE WHEN (SELECT '$.groups[' || key || '].description' FROM json_each(section.json, '$.groups') WHERE json_extract(value, '$.id') = 'events' AND json_extract(value, '$.description') = 'Specialist seminars, hands-on workshops and partnership signings hosted at the lab between 2019 and 2023.') IS NOT NULL THEN json_set(json_set(json, '$.items', (SELECT json_group_array(json(v) ORDER BY part, o) FROM (SELECT value AS v, 0 AS part, CAST(key AS INTEGER) AS o FROM json_each(section.json, '$.items') WHERE json_extract(value, '$.kind') NOT IN (SELECT k.value FROM json_each(section.json, '$.groups') g, json_each(g.value, '$.kinds') k WHERE json_extract(g.value, '$.id') = 'events') AND json_extract(value, '$.id') NOT IN ('ws26-fablab-intro', 'ws26-lantern', 'ws26-bouquet', 'ws26-decoden', 'ws26-beads', 'ws26-glass', 'ws26-clay', 'ws26-git', 'ws26-mech-design', 'uav-f1tenth', 'ws26-machines') UNION ALL SELECT value, 1, CAST(key AS INTEGER) FROM json_each('[{"id":"ws26-fablab-intro","kind":"workshop","date":"21 Oct 2026","title":"Getting started with FabLab","description":"An introduction to the FabLab creative space for students. Participants got to know the technology equipment, learned how to use it and how to apply it in study, research and practice — turning ideas into real products.","venue":"EIU FabLab, Block B11","registerClosed":true},{"id":"ws26-lantern","kind":"workshop","date":"23 Sep 2026","title":"Mid-Autumn lantern making","description":"Make your own Mid-Autumn lantern from wood and acrylic, cut and engraved on the laser cutter. Participants were guided through sketching ideas and choosing a design, assembling it, then decorating and finishing the lantern.","time":"Wednesday, 2:00–4:00 pm","venue":"Room 204, Block B11, EIU FabLab","fee":"60,000 VND","registerClosed":true},{"id":"ws26-bouquet","kind":"workshop","date":"12 Aug 2026","title":"Youthful bouquets","description":"A DIY workshop making handmade bouquets for loved ones or for yourself. Participants combined small flower stems with hand-modelled characters into a bouquet of their own, with a wish carried in every detail.","time":"Wednesday, 2:00–4:00 pm","venue":"Room 202, Block B11, EIU FabLab","registerClosed":true},{"id":"ws26-decoden","kind":"workshop","date":"22 Jul 2026","title":"Decoden cream-glue decorating","description":"A DIY workshop decorating everyday items with cream glue and charms. Participants decorated hairbrushes, phone cases, mirrors and other accessories, each with its own personality.","time":"Wednesday, morning 9:00–11:00 am, afternoon 2:00–4:00 pm","venue":"Room 202, Block B11, EIU FabLab","fee":"35,000 VND per person","registerClosed":true},{"id":"ws26-beads","kind":"workshop","date":"1 Jul 2026","title":"Beaded bracelets","description":"Part of the DIY craft workshop series. Participants designed and strung beads into a bracelet of their own, free to choose colours and details, and took it home. Each piece is a small gift showing the care and personality of its maker.","time":"Wednesday, morning and afternoon sessions","venue":"Room 305, Block B11, EIU FabLab","registerClosed":true},{"id":"ws26-glass","kind":"workshop","date":"10 Jun 2026","title":"Glass painting","description":"A cheerful, relaxing DIY workshop for students after class. Everyone designed and decorated a glass in their own style. The session was lively, and every glass became a piece bearing its maker’s mark.","time":"Wednesday, morning 9:00–11:00 am, afternoon 2:00–4:00 pm","venue":"Room 305, Block B11, EIU FabLab","fee":"35,000 VND per person (materials included)","registerClosed":true},{"id":"ws26-clay","kind":"workshop","date":"27 May 2026","title":"Creating with Clay","description":"A DIY workshop to unwind and connect after class. Participants used Mont Marte air-dry clay and acrylic paint to model small, cute pieces to take home. Students and university staff joined in together.","time":"Wednesday, session 1 9:00–11:00 am, session 2 2:00–4:00 pm","venue":"Room 209, Block B11, EIU FabLab","fee":"35,000 VND per person (materials included)","registerClosed":true},{"id":"ws26-git","kind":"workshop","date":"20 May 2026","title":"Getting started with Git and GitHub","description":"A workshop on managing source code, working in teams and “rescuing code” for course projects. Participants learned Git and GitHub from scratch: the pull → add → commit → push workflow, working with branches (branch, merge) and hands-on teamwork. Many programming enthusiasts took part.","time":"Wednesday, 2:00–4:00 pm","venue":"Room 305, Block B11, EIU FabLab","registerClosed":true},{"id":"ws26-mech-design","kind":"workshop","date":"15 Apr 2026","title":"Mechanical design basics","description":"For engineering-minded students who need mechanical design for course or personal projects. Topics covered mechanical design thinking, technical standards and hands-on design in software, with a sharing session and plenty of focused practice.","time":"Wednesday, 2:00–4:00 pm","venue":"Room 305, Block B11, EIU FabLab","registerClosed":true},{"id":"uav-f1tenth","kind":"workshop","date":"27 Jan 2026","title":"UAV & F1TENTH workshop series","description":"A long-running workshop series for students interested in autonomous robots, starting 27 January 2026. Phase 1 builds the foundations: Ubuntu and Linux, core maths, ROS 2 and its key concepts, and ROS 2 programming in simulation before moving to real drones and F1TENTH cars — preparing for the advanced phase 2.","details":"Getting started with Ubuntu and the Linux environment.\n\nCore maths review: calculus, linear algebra, probability and statistics.\n\nROS 2 and its core concepts: Workspace, Package, Node, Topic, Service, Action.\n\nROS 2 programming in simulation, then connecting to real models such as drones and F1TENTH cars.","registerClosed":true},{"id":"ws26-machines","kind":"workshop","date":"14 Jan 2026","title":"Using the FabLab workshop machines","description":"For students who love making, engineering and DIY, or who need machines for course and personal projects. Participants learned the procedures and safety rules for working at FabLab and practised hands-on with basic mechanical machines, so they can use them confidently for study, research and building products.","time":"Wednesday, morning 9:00–11:00 am, afternoon 2:00–4:00 pm","venue":"Room 204, Block B11, EIU FabLab","registerClosed":true}]'))), '$.timeLabel', 'Time', '$.venueLabel', 'Venue', '$.feeLabel', 'Fee'), (SELECT '$.groups[' || key || '].description' FROM json_each(section.json, '$.groups') WHERE json_extract(value, '$.id') = 'events' AND json_extract(value, '$.description') = 'Specialist seminars, hands-on workshops and partnership signings hosted at the lab between 2019 and 2023.'), 'Technical workshops for students, hands-on DIY craft workshops and FabLab orientation sessions in 2026.') ELSE json_set(json, '$.items', (SELECT json_group_array(json(v) ORDER BY part, o) FROM (SELECT value AS v, 0 AS part, CAST(key AS INTEGER) AS o FROM json_each(section.json, '$.items') WHERE json_extract(value, '$.kind') NOT IN (SELECT k.value FROM json_each(section.json, '$.groups') g, json_each(g.value, '$.kinds') k WHERE json_extract(g.value, '$.id') = 'events') AND json_extract(value, '$.id') NOT IN ('ws26-fablab-intro', 'ws26-lantern', 'ws26-bouquet', 'ws26-decoden', 'ws26-beads', 'ws26-glass', 'ws26-clay', 'ws26-git', 'ws26-mech-design', 'uav-f1tenth', 'ws26-machines') UNION ALL SELECT value, 1, CAST(key AS INTEGER) FROM json_each('[{"id":"ws26-fablab-intro","kind":"workshop","date":"21 Oct 2026","title":"Getting started with FabLab","description":"An introduction to the FabLab creative space for students. Participants got to know the technology equipment, learned how to use it and how to apply it in study, research and practice — turning ideas into real products.","venue":"EIU FabLab, Block B11","registerClosed":true},{"id":"ws26-lantern","kind":"workshop","date":"23 Sep 2026","title":"Mid-Autumn lantern making","description":"Make your own Mid-Autumn lantern from wood and acrylic, cut and engraved on the laser cutter. Participants were guided through sketching ideas and choosing a design, assembling it, then decorating and finishing the lantern.","time":"Wednesday, 2:00–4:00 pm","venue":"Room 204, Block B11, EIU FabLab","fee":"60,000 VND","registerClosed":true},{"id":"ws26-bouquet","kind":"workshop","date":"12 Aug 2026","title":"Youthful bouquets","description":"A DIY workshop making handmade bouquets for loved ones or for yourself. Participants combined small flower stems with hand-modelled characters into a bouquet of their own, with a wish carried in every detail.","time":"Wednesday, 2:00–4:00 pm","venue":"Room 202, Block B11, EIU FabLab","registerClosed":true},{"id":"ws26-decoden","kind":"workshop","date":"22 Jul 2026","title":"Decoden cream-glue decorating","description":"A DIY workshop decorating everyday items with cream glue and charms. Participants decorated hairbrushes, phone cases, mirrors and other accessories, each with its own personality.","time":"Wednesday, morning 9:00–11:00 am, afternoon 2:00–4:00 pm","venue":"Room 202, Block B11, EIU FabLab","fee":"35,000 VND per person","registerClosed":true},{"id":"ws26-beads","kind":"workshop","date":"1 Jul 2026","title":"Beaded bracelets","description":"Part of the DIY craft workshop series. Participants designed and strung beads into a bracelet of their own, free to choose colours and details, and took it home. Each piece is a small gift showing the care and personality of its maker.","time":"Wednesday, morning and afternoon sessions","venue":"Room 305, Block B11, EIU FabLab","registerClosed":true},{"id":"ws26-glass","kind":"workshop","date":"10 Jun 2026","title":"Glass painting","description":"A cheerful, relaxing DIY workshop for students after class. Everyone designed and decorated a glass in their own style. The session was lively, and every glass became a piece bearing its maker’s mark.","time":"